CREATE OR REPLACE FUNCTION private.amazon_effective_vat_amount(p_owner uuid, p_gross numeric, p_explicit_vat numeric, p_is_business boolean)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rate numeric;
begin
  if p_explicit_vat is not null then return p_explicit_vat; end if;
  if coalesce(p_is_business,false) then return 0::numeric; end if;
  if p_gross is null then return null; end if;

  begin
    v_rate:=private.amazon_setting_text(p_owner,'defaultVatRate','21')::numeric;
  exception when others then
    v_rate:=21;
  end;
  v_rate:=greatest(0,least(100,v_rate));
  if v_rate=0 then return 0::numeric; end if;
  return p_gross-(p_gross/(1+(v_rate/100)));
end;
$function$

CREATE OR REPLACE FUNCTION private.amazon_rate_to_eur(p_currency text, p_event_date date)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source text:=upper(coalesce(nullif(trim(p_currency),''),'EUR'));
  v_policy text:='last_known';
  v_rate numeric;
  v_owner uuid;
begin
  if p_event_date is null then return null; end if;
  if v_source='EUR' then return 1; end if;

  v_owner:=private.app_workspace_owner_id();
  if v_owner is not null then
    select lower(coalesce(nullif(trim(s.config->'amazon'->>'fxMissingRatePolicy'),''),'last_known'))
      into v_policy
    from public.app_settings s
    where s.owner_id=v_owner
    limit 1;
  end if;
  v_policy:=coalesce(v_policy,'last_known');

  select r.rate_to_eur
    into v_rate
  from public.amazon_fx_rates r
  where r.currency_code=v_source
    and (
      (v_policy='exclude' and r.rate_date=p_event_date)
      or
      (v_policy<>'exclude' and r.rate_date<=p_event_date)
    )
  order by r.rate_date desc
  limit 1;

  return v_rate;
end;
$function$
